BEGIN;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE providers (id text PRIMARY KEY, name text NOT NULL UNIQUE, lifecycle text NOT NULL);
CREATE TABLE provider_accounts (id text PRIMARY KEY, provider_id text NOT NULL REFERENCES providers(id), secret_ref text NOT NULL CHECK (secret_ref LIKE 'secret://%'), region text NOT NULL, lifecycle text NOT NULL, UNIQUE(id,provider_id));
CREATE TABLE provider_models (id text PRIMARY KEY, provider_id text NOT NULL REFERENCES providers(id), account_id text NOT NULL, name text NOT NULL, lifecycle text NOT NULL, capabilities text[] NOT NULL, context_limit integer NOT NULL CHECK(context_limit>0), output_limit integer NOT NULL CHECK(output_limit>0), health text NOT NULL, latency_ms integer NOT NULL CHECK(latency_ms>=0), quality double precision NOT NULL CHECK(quality BETWEEN 0 AND 1), reliability double precision NOT NULL CHECK(reliability BETWEEN 0 AND 1), FOREIGN KEY(account_id,provider_id) REFERENCES provider_accounts(id,provider_id), UNIQUE(id,account_id,provider_id));
CREATE TABLE model_price_versions (id uuid PRIMARY KEY, model_id text NOT NULL REFERENCES provider_models(id), effective_from timestamptz NOT NULL, effective_to timestamptz, input_usd_micros_per_million bigint NOT NULL CHECK(input_usd_micros_per_million>=0), output_usd_micros_per_million bigint NOT NULL CHECK(output_usd_micros_per_million>=0), CHECK(effective_to IS NULL OR effective_to>effective_from), EXCLUDE USING gist (model_id WITH =, tstzrange(effective_from,effective_to,'[)') WITH &&));
CREATE TABLE model_evaluations (id text PRIMARY KEY, model_id text NOT NULL REFERENCES provider_models(id), suite text NOT NULL, quality double precision NOT NULL CHECK(quality BETWEEN 0 AND 1), success_rate double precision NOT NULL CHECK(success_rate BETWEEN 0 AND 1), security_pass boolean NOT NULL, occurred_at timestamptz NOT NULL, reviewer_agent_id text NOT NULL);
CREATE TABLE provider_usage (id text PRIMARY KEY, provider_id text NOT NULL REFERENCES providers(id), account_id text NOT NULL REFERENCES provider_accounts(id), model_id text NOT NULL REFERENCES provider_models(id), agent_id text NOT NULL, project_id text NOT NULL, contract_id text NOT NULL, task_id text NOT NULL, attempt_id text NOT NULL, input_tokens integer NOT NULL CHECK(input_tokens>=0), output_tokens integer NOT NULL CHECK(output_tokens>=0), cost_usd_micros bigint NOT NULL CHECK(cost_usd_micros>=0), occurred_at timestamptz NOT NULL, FOREIGN KEY(model_id,account_id,provider_id) REFERENCES provider_models(id,account_id,provider_id));
CREATE TRIGGER model_evaluations_immutable BEFORE UPDATE OR DELETE ON model_evaluations FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TRIGGER provider_usage_immutable BEFORE UPDATE OR DELETE ON provider_usage FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
COMMIT;
